window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-accad4b36fa2ad33"]={"versions": [{"id": "FIG-accad4b36fa2ad33", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink- und Stateflow-Modellierungsansicht mit Eigenschaftsdialogen (Screenshot der MATLAB/Simulink/Stateflow-Umgebung) im Kontext des AUTOSAR Simulink Styleguides. Dargestellt ist eine Simulink-Bibliothek (<code>swc_communication_delay_config_timeout_lib</code>) zur Definition und Bereitstellung global exportierter grafischer Stateflow-Funktionen zur Kapselung von RTE-Zugriffsoperationen (<code>RTE_Read</code>, <code>RTE_Write</code>) sowie deren Aufruf in separaten Charts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Struktur umfasst folgende Elemente:</p>\n<ul class=\"fig-list\">\n<li>Simulink-Bibliothek <code>swc_communication_delay_config_timeout_lib</code> mit den Bibliotheksblöcken:</li>\n<li>Stateflow-Chart <code>RTE_Read_Write_Implementation</code></li>\n<li>Verwendende Charts / Subsysteme <code>RTE_Write</code> (mit Eingangssignal <code>u</code>) und <code>RTE_Read</code> (mit Ausgangssignal <code>y</code>)</li>\n<li>Stateflow-Chart <code>RTE_Read_Write_Implementation</code> enthält zwei grafische Funktionen:</li>\n<li><code>function y=RTE_Read(Id)</code>: Liest Daten über die Zuweisung <code>{y=localDataOut[Id];}</code></li>\n<li><code>function RTE_Write(Id,u)</code>: Schreibt Eingangsdaten über die Aktionen <code>{localDataIn[Id]=u; RTE_Copy(Id);}</code></li>\n<li>Eigenschaftsdialog <code>Chart RTE_Read_Write_Implementation</code>:</li>\n<li>Name: <code>RTE_Read_Write_Implementation</code></li>\n<li>Parent / Machine: <code>swc_communication_delay_config_timeout_lib</code></li>\n<li>Update method: <code>Inherited</code></li>\n<li>Aktivierte Optionen: <code>Export Chart Level Graphical Functions (Make Global)</code> und <code>Use Strong Data Typing with Simulink I/O</code></li>\n<li>Deaktivierte Optionen: <code>User specified state/transition execution order</code>, <code>Execute (enter) Chart At Initialization</code>, <code>Enable C-bit operations</code></li>\n<li>Aufrufendes Chart (<code>RTE_Write</code>):</li>\n<li>Standard-Transition führt den globalen Funktionsaufruf <code>{ RTE_Write(i,u); }</code> zu einem Verbindungsübergangspunkt (Junction) aus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die grafischen Funktionen innerhalb von <code>RTE_Read_Write_Implementation</code> definieren wiederverwendbare Implementierungslogik für den Lese- und Schreibzugriff:</p>\n<ul class=\"fig-list\">\n<li>Bei Aufruf von <code>RTE_Read(Id)</code> wird das Element am Index <code>Id</code> aus <code>localDataOut</code> dem Rückgabewert <code>y</code> zugewiesen.</li>\n<li>Bei Aufruf von <code>RTE_Write(Id, u)</code> wird der Parameter <code>u</code> am Index <code>Id</code> in <code>localDataIn</code> gespeichert und anschließend <code>RTE_Copy(Id)</code> aufgerufen.</li>\n<li>Externe Stateflow-Charts wie <code>RTE_Write</code> rufen über Default-Transitionen beim Eintritt oder der Ausführung direkt die globale Funktion <code>RTE_Write(i,u)</code> auf, wodurch die Kapselung der Zugriffsmechanismen ohne explizite Verdrahtung realisiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht Modellierungsrichtlinien für AUTOSAR-Softwarekomponenten in Simulink/Stateflow:</p>\n<ul class=\"fig-list\">\n<li>Globale Stateflow-Funktionen (<code>Export Chart Level Graphical Functions (Make Global)</code>) ermöglichen die modulare Kapselung und Wiederverwendung von RTE-Kommunikationsmustern innerhalb einer Modellbibliothek.</li>\n<li>Die Option <code>Use Strong Data Typing with Simulink I/O</code> erzwingt strikte Typkonsistenz zwischen Stateflow und Simulink-Schnittstellen gemäß AUTOSAR-Typanforderungen.</li>\n<li>Die Ausführungsmethode steht auf <code>Inherited</code>, um die Abtastrate dynamisch aus dem Komponentenkontext abzuleiten.</li>\n</ul>"}, {"id": "FIG-65a659bff1109ddb", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink- und Stateflow-Modellierungsansicht mit Eigenschaftsdialogen (Screenshot der MATLAB/Simulink/Stateflow-Umgebung) im Kontext des AUTOSAR Simulink Styleguides. Dargestellt ist eine Simulink-Bibliothek (<code>swc_communication_delay_config_timeout_lib</code>) zur Definition und Bereitstellung global exportierter grafischer Stateflow-Funktionen zur Kapselung von RTE-Zugriffsoperationen (<code>RTE_Read</code>, <code>RTE_Write</code>) sowie deren Aufruf in separaten Charts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Struktur umfasst folgende Elemente:</p>\n<ul class=\"fig-list\">\n<li>Simulink-Bibliothek <code>swc_communication_delay_config_timeout_lib</code> mit den Bibliotheksblöcken:</li>\n<li>Stateflow-Chart <code>RTE_Read_Write_Implementation</code></li>\n<li>Verwendende Charts / Subsysteme <code>RTE_Write</code> (mit Eingangssignal <code>u</code>) und <code>RTE_Read</code> (mit Ausgangssignal <code>y</code>)</li>\n<li>Stateflow-Chart <code>RTE_Read_Write_Implementation</code> enthält zwei grafische Funktionen:</li>\n<li><code>function y=RTE_Read(Id)</code>: Liest Daten über die Zuweisung <code>{y=localDataOut[Id];}</code></li>\n<li><code>function RTE_Write(Id,u)</code>: Schreibt Eingangsdaten über die Aktionen <code>{localDataIn[Id]=u; RTE_Copy(Id);}</code></li>\n<li>Eigenschaftsdialog <code>Chart RTE_Read_Write_Implementation</code>:</li>\n<li>Name: <code>RTE_Read_Write_Implementation</code></li>\n<li>Parent / Machine: <code>swc_communication_delay_config_timeout_lib</code></li>\n<li>Update method: <code>Inherited</code></li>\n<li>Aktivierte Optionen: <code>Export Chart Level Graphical Functions (Make Global)</code> und <code>Use Strong Data Typing with Simulink I/O</code></li>\n<li>Deaktivierte Optionen: <code>User specified state/transition execution order</code>, <code>Execute (enter) Chart At Initialization</code>, <code>Enable C-bit operations</code></li>\n<li>Aufrufendes Chart (<code>RTE_Write</code>):</li>\n<li>Standard-Transition führt den globalen Funktionsaufruf <code>{ RTE_Write(i,u); }</code> zu einem Verbindungsübergangspunkt (Junction) aus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die grafischen Funktionen innerhalb von <code>RTE_Read_Write_Implementation</code> definieren wiederverwendbare Implementierungslogik für den Lese- und Schreibzugriff:</p>\n<ul class=\"fig-list\">\n<li>Bei Aufruf von <code>RTE_Read(Id)</code> wird das Element am Index <code>Id</code> aus <code>localDataOut</code> dem Rückgabewert <code>y</code> zugewiesen.</li>\n<li>Bei Aufruf von <code>RTE_Write(Id, u)</code> wird der Parameter <code>u</code> am Index <code>Id</code> in <code>localDataIn</code> gespeichert und anschließend <code>RTE_Copy(Id)</code> aufgerufen.</li>\n<li>Externe Stateflow-Charts wie <code>RTE_Write</code> rufen über Default-Transitionen beim Eintritt oder der Ausführung direkt die globale Funktion <code>RTE_Write(i,u)</code> auf, wodurch die Kapselung der Zugriffsmechanismen ohne explizite Verdrahtung realisiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht Modellierungsrichtlinien für AUTOSAR-Softwarekomponenten in Simulink/Stateflow:</p>\n<ul class=\"fig-list\">\n<li>Globale Stateflow-Funktionen (<code>Export Chart Level Graphical Functions (Make Global)</code>) ermöglichen die modulare Kapselung und Wiederverwendung von RTE-Kommunikationsmustern innerhalb einer Modellbibliothek.</li>\n<li>Die Option <code>Use Strong Data Typing with Simulink I/O</code> erzwingt strikte Typkonsistenz zwischen Stateflow und Simulink-Schnittstellen gemäß AUTOSAR-Typanforderungen.</li>\n<li>Die Ausführungsmethode steht auf <code>Inherited</code>, um die Abtastrate dynamisch aus dem Komponentenkontext abzuleiten.</li>\n</ul>"}], "trans": [{"from": "FIG-accad4b36fa2ad33", "to": "FIG-65a659bff1109ddb", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
